const rows = $input.all().map(item => item.json);

function csvCell(value) {
  if (value === null || value === undefined || value === '') return '';
  const str = String(value);
  if (/[;\n\r"]/.test(str)) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

function extractSum(field) {
  if (!field) return null;
  const match = String(field).match(/\b(1800|2500|3600|5000)\b/);
  return match ? parseInt(match[0]) : null;
}

const now = new Date();
const pad = n => String(n).padStart(2, '0');

const currentDate =
  now.getFullYear() + '-' +
  pad(now.getMonth() + 1) + '-' +
  pad(now.getDate()) + ' ' +
  pad(now.getHours()) + ':' +
  pad(now.getMinutes()) + ':' +
  pad(now.getSeconds());

const formatDate = date =>
  date.getFullYear() + '-' +
  pad(date.getMonth() + 1) + '-' +
  pad(date.getDate());

const endDate = formatDate(now);
const start = new Date(now);
start.setDate(start.getDate() - 7);
const startDate = formatDate(start);

const fileName = `fondoruso_payments_${startDate}_to_${endDate}.csv`;

const recordIds = [];
const csvLines = [];

for (const row of rows) {
  const sum = extractSum(row['Payment']);
  if (sum === null) continue;

  const comment = row['Name'] || '';
  const line = sum + ';;Взносы;;' + currentDate + ';' + csvCell(comment) + ';';
  csvLines.push(line);
  recordIds.push(row.Id);
}

const csvContent = csvLines.join('\n');
const bom = Buffer.from([0xEF, 0xBB, 0xBF]);
const csvBuffer = Buffer.concat([bom, Buffer.from(csvContent, 'utf8')]);

return [{
  json: {
    recordIds,
    rowCount: recordIds.length,
    fileName,
    periodStart: startDate,
    periodEnd: endDate
  },
  binary: {
    attachment: {
      data: csvBuffer.toString('base64'),
      mimeType: 'text/csv',
      fileName: fileName,
      fileExtension: 'csv'
    }
  }
}];
